
import pandas as pd
import matplotlib.pyplot as plt

# Read data generated by the C program
data = pd.read_csv("leaky_data.csv")

# Plot packet counts
plt.plot(data["Time"], data["Stored"],
         marker="o", label="Packets remaining")

plt.plot(data["Time"], data["Incoming"],
         marker="s", label="Incoming packets")

# Constant bucket capacity
plt.axhline(y=10, linestyle="--",
            label="Bucket capacity (B=10)")

plt.xlabel("Time Units")
plt.ylabel("Number of Packets")
plt.title("Leaky Bucket Algorithm")

plt.xticks(data["Time"])
plt.grid(True)
plt.legend()
plt.tight_layout()
plt.show()
